            return [1, 0]
        if sx == w - 1 and sy < h - 1:
            return [0, 1]
        if sy == h - 1 and sx > 0:
            return [-1, 0]
        if sx == 0 and sy > 0:
            return [0, -1]
        target = [0, 0]
    dx = 0 if target[0] == sx else (1 if target[0] > sx else -1)
    dy = 0 if target[1] == sy else (1 if target[1] > sy else -1)
    return [dx, dy]

